import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import username from 'flarum/common/helpers/username';
import classList from 'flarum/common/utils/classList';
import { call, number, pushUsers, t, unit } from '../common';
/** A goal's ten biggest helpers, and where the viewer stands. */
export default class TopModal extends Modal {
  data = null;
  oninit(vnode) {
    super.oninit(vnode);
    call('GET', `/${this.attrs.goal.id}`).then(data => {
      pushUsers(data.users);
      this.data = data;
      m.redraw();
    });
  }
  className() {
    return 'GoalTopModal Modal--small';
  }
  title() {
    return t('top_modal.title');
  }
  content() {
    const goal = this.data?.goal;
    if (!goal) return m("div", {
      className: "Modal-body"
    }, m(LoadingIndicator, null));
    const me = app.session.user;
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "GoalTopModal-goal"
    }, goal.title), goal.top.length ? m("ol", {
      className: "GoalTopModal-list"
    }, goal.top.map(([id, count], i) => {
      const u = app.store.getById('users', String(id));
      return m("li", {
        className: classList('GoalTopModal-row', me && String(me.id()) === String(id) && 'is-me')
      }, m("span", {
        className: "GoalTopModal-rank"
      }, i < 3 ? ['🥇', '🥈', '🥉'][i] : i + 1), u ? m(Link, {
        className: "GoalTopModal-who",
        href: app.route.user(u)
      }, m(Avatar, {
        user: u
      }), " ", username(u)) : m("span", {
        className: "GoalTopModal-who"
      }, username(null)), m("span", {
        className: "GoalTopModal-count"
      }, number(count), " ", m("small", null, unit(goal, count))));
    })) : m("p", null, t('top_modal.empty')), me && goal.rank && goal.rank > 10 && m("p", {
      className: "GoalTopModal-mine"
    }, t('top_modal.you'), ": ", t('goal.rank', {
      rank: goal.rank
    }), " \xB7 ", number(goal.mine || 0), " ", unit(goal, goal.mine || 0)));
  }
}
flarum.reg.add('ernestdefoe-community-goals', 'forum/components/TopModal', TopModal);